      "path": "pyproject.toml",
      "content": "[project]\nname = \"ouroboros-ai\"\ndynamic = [\"version\"]\ndescription = \"Pins an acceptance spec and omits any verify command or expected output from the worker's contract. Works with Claude Code, Codex CLI, OpenCode and 10 more runtimes.\"\nreadme = \"README.md\"\nauthors = [\n    { name = \"Q00\", email = \"jqyu.lee@gmail.com\" }\n]\nrequires-python = \">=3.12\"\nkeywords = [\n    \"agent-os\",\n    \"agentic-loop\",\n    \"ai-agent\",\n    \"ai-coding-agent\",\n    \"claude-code\",\n    \"cli\",\n    \"developer-tools\",\n    \"llm-orchestration\",\n    \"loop-engineering\",\n    \"mcp\",\n    \"prompt-engineering\",\n    \"socratic-method\",\n    \"spec-driven-development\",\n]\nclassifiers = [\n    \"Development Status :: 4 - Beta\",\n    \"Environment :: Console\",\n    \"Intended Audience :: Developers\",\n    \"License :: OSI Approved :: MIT License\",\n    \"Operating System :: OS Independent\",\n    \"Programming Language :: Python :: 3\",\n    \"Programming Language :: Python :: 3.12\",\n    \"Programming Language :: Python :: 3.13\",\n    \"Programming Language :: Python :: 3.14\",\n    \"Topic :: Software Development :: Build Tools\",\n    \"Topic :: Software Development :: Code Generators\",\n]\ndependencies = [\n    \"aiosqlite>=0.20.0,<1.0.0\",\n    \"anyio>=4.0.0,<5.0.0\",\n    \"click>=8.1.0,<9.0.0\",\n    \"jsonschema>=4.21.0,<5.0.0\",\n    \"packaging>=25.0,<27.0\",\n    \"pydantic>=2.0.0,<3.0.0\",\n    \"prompt-toolkit>=3.0.0,<4.0.0\",\n    # Ceiling is deliberately tighter than the major-version bounds around it:\n    # this parses `.env`, a documented trust boundary (see\n    # `UNTRUSTED_ENV_DENYLIST` in config/untrusted_env.py), so only patch releases\n    # flow without review. An exact pin would be tighter still, but\n    # `test_runtime_and_optional_dependencies_have_upper_bounds` reserves\n    # `==` for the optional extras; core runtime deps stay bounded ranges.\n    # uv.lock pins the exact version for reproducible installs regardless.\n    \"python-dotenv>=1.2.2,<1.3.0\",\n    \"pyyaml>=6.0.0,<7.0.0\",\n    \"rich>=13.0.0,<16.0.0\",\n    \"sqlalchemy[asyncio]>=2.0.0,<3.0.0\",\n    \"structlog>=24.0.0,<27.0.0\",\n    \"typer>=0.12.0,<0.28.0\",\n]\n\n[project.urls]\nHomepage = \"https://ouroboros.page/\"\nRepository = \"https://github.com/Q00/ouroboros\"\n\"Bug Tracker\" = \"https://github.com/Q00/ouroboros/issues\"\nSponsor = \"https://github.com/sponsors/Q00\"\n\n[project.optional-dependencies]\n# Exact-pinned (not ranges) on purpose: a future compromised \"latest\" must not\n# be auto-pulled on a fresh PyPI install (pipx / uv tool / pip resolve from\n# this metadata, NOT from uv.lock). Motivated by the 2026-03 litellm\n# 1.82.7/1.82.8 supply-chain incident. Updates land via reviewed Dependabot\n# PRs; uv.lock additionally hash-pins the full transitive graph for repo/CI.\n# Claude's default runtime preserves the Agent SDK and its MCP 1.x graph. The\n# MCP 2 server runs in a separate process/profile; these extras must never be\n# selected in one interpreter.\n# claude-agent-sdk 0.2.144 dropped its own MCP 1.x ceiling; the profile\n# contract (MCP 1.x graph) is preserved by pinning it here explicitly.\nclaude = [\"claude-agent-sdk==0.2.168\", \"anthropic==1.15.0\", \"mcp==1.28.1\"]\nclaude-cli = []\n# Explicit alias for automation and migrations that want to spell out the SDK\n# transport rather than rely on the historical `[claude]` name.\nclaude-sdk = [\"claude-agent-sdk==0.2.168\", \"anthropic==1.15.0\", \"mcp==1.28.1\"]\ncopilot = []\nlitellm = [\"litellm==1.91.0; python_version < '3.14'\"]\ndashboard = []\nmcp = [\"mcp==2.3.0\"]\ntui = [\"textual==8.2.8\", \"textual-serve==1.1.3\"]\n# `[all]` remains the MCP 1.x application bundle. The MCP 2 server profile is\n# explicit and isolated; `[all,mcp]` is intentionally unsupported.\nall = [\"ouroboros-ai[claude,copilot,litellm,tui,dashboard]\"]\n\n[project.scripts]\nooo = \"ouroboros.cli.entrypoint:main\"\nouroboros = \"ouroboros.cli.entrypoint:main\"\nozo = \"ouroboros.cli.commands.zcode:app\"\n\n[build-system]\nrequires = [\"hatchling\", \"hatch-vcs\"]\nbuild-backend = \"hatchling.build\"\n\n[tool.hatch.version]\nsource = \"vcs\"\n\n[tool.hatch.version.raw-options]\nversion_scheme = \"guess-next-dev\"\nlocal_scheme = \"no-local-version\"\n\n[tool.hatch.build.hooks.vcs]\nversion-file = \"src/ouroboros/_version.py\"\n\n[tool.hatch.build]\nexclude = [\n    \"/.smoke-home\",\n    \"**/node_modules\",\n    \"**/target\",\n    \"**/__pycache__\",\n    \"/.mypy_cache\",\n    \"/.pytest_cache\",\n    \"/.ruff_cache\",\n    \"/.venv\",\n    \"/coverage.xml\",\n    \"/.coverage\",\n    # Keep docs (esp. the 7.5MB docs/images/ouroboros.png) out of the sdist —\n    # they are never imported and the wheel already excludes them via\n    # packages=[\"src/ouroboros\"]. Shipping them re-bloated every dev build and\n    # pushed the PyPI project past its 10GB storage cap.\n    \"/docs\",\n]\n\n[tool.hatch.build.targets.wheel]\npackages = [\"src/ouroboros\"]\n# Scoped to wheel only: prevent the `packages=` sweep from shipping these\n# assets, so the force-include below is the single source of truth and we\n# avoid duplicate ZIP local headers (PyPI rejects those). The sdist keeps\n# the files at their natural source path so rebuilds from sdist reproduce\n# the same wheel via this same config.\nexclude = [\n    \"src/ouroboros/opencode/plugin/**\",\n    \"src/ouroboros/interview_adapters/packs/**\",\n    \"src/ouroboros/plugin/schemas/**\",\n    \"src/ouroboros/profiles/**\",\n]\n\n[tool.hatch.build.targets.wheel.force-include]\n\"skills\" = \"ouroboros/skills\"\n# Explicit inclusion so `importlib.resources.files(\"ouroboros.opencode.plugin\")`\n# reliably finds ouroboros-bridge.ts / package.json / tsconfig.json in the\n# installed wheel, independent of hatchling's implicit asset handling.\n\"src/ouroboros/opencode/plugin\" = \"ouroboros/opencode/plugin\"\n# Same pattern for the vendored UserLevel plugin schemas — `_load_schema`\n# in `ouroboros.plugin.manifest` resolves them via `importlib.resources`,\n# so they must reach the installed wheel as package data, not just the\n# source tree.\n\"src/ouroboros/plugin/schemas\" = \"ouroboros/plugin/schemas\"\n# Built-in interview glossary packs. The loader resolves these through\n# importlib.resources, so the wheel must include them as package data exactly\n# once.\n\"src/ouroboros/interview_adapters/packs\" = \"ouroboros/interview_adapters/packs\"\n# Execution profile YAMLs (RFC v2 #830). The loader resolves them via\n# Path(__file__).parent.parent / \"profiles\", so they must ship with the wheel.\n\"src/ouroboros/profiles\" = \"ouroboros/profiles\"\n\n[dependency-groups]\ndev = [\n    \"ouroboros-ai[tui]\",\n    \"mypy>=1.19.1\",\n    \"pre-commit>=4.5.1\",\n    \"pytest>=9.0.2\",\n    \"pytest-asyncio>=1.3.0\",\n    \"pytest-cov>=7.0.0\",\n    \"pytest-xdist>=3.6\",\n    \"ruff>=0.14.11\",\n    \"types-pyyaml>=6.0.12.20250915\",\n]\nlitellm-test = [\n    \"ouroboros-ai[litellm]\",\n]\nmcp-test = [\n    \"mcp==2.3.0\",\n]\nclaude-sdk-test = [\n    \"ouroboros-ai[claude-sdk]\",\n]\n\n[tool.uv.dependency-groups]\nlitellm-test = { requires-python = \">=3.12,<3.14\" }\n\n[tool.uv]\n# The official Claude Agent SDK still embeds MCP 1.x internals. Declare every\n# SDK spelling incompatible with the MCP 2 profile and test group. The\n# dependency-free `[claude-cli]` profile remains compatible with `[mcp]`.\nconflicts = [\n    [{ extra = \"claude\" }, { extra = \"mcp\" }],\n    [{ extra = \"claude\" }, { group = \"mcp-test\" }],\n    [{ extra = \"claude-sdk\" }, { extra = \"mcp\" }],\n    [{ extra = \"claude-sdk\" }, { group = \"mcp-test\" }],\n    [{ extra = \"all\" }, { extra = \"mcp\" }],\n    [{ extra = \"all\" }, { group = \"mcp-test\" }],\n]\n\n[tool.mypy]\npython_version = \"3.12\"\nignore_missing_imports = true\ndisable_error_code = [\n    \"union-attr\",\n    \"arg-type\",\n    \"return-value\",\n    \"assignment\",\n    \"attr-defined\",\n    \"misc\",\n    \"call-arg\",\n    \"override\",\n    \"list-item\",\n    \"dict-item\",\n    \"operator\",\n    \"str-bytes-safe\",\n    \"no-any-return\",\n    \"import-untyped\",\n]\n\n[tool.pytest.ini_options]\n# asyncio_mode = \"auto\" per project-context.md\nasyncio_mode = \"auto\"\nasyncio_default_fixture_loop_scope = \"function\"\ntestpaths = [\"tests\"]\npython_files = [\"test_*.py\"]\npython_classes = [\"Test*\"]\npython_functions = [\"test_*\"]\nmarkers = [\n    \"integration: integration tests that exercise cross-component behavior\",\n    \"slow: integration tests that build artifacts or call subprocesses\",\n    \"performance: isolated performance budgets; exclude from parallel correctness suites\",\n]\n\n[tool.ruff]\nline-length = 100\ntarget-version = \"py312\"\nexclude = [\"src/ouroboros/_version.py\"]\n\n[tool.ruff.lint]\nselect = [\n    \"E\",     # pycodestyle errors\n    \"W\",     # pycodestyle warnings\n    \"F\",     # Pyflakes\n    \"I\",     # isort\n    \"B\",     # flake8-bugbear\n    \"C4\",    # flake8-comprehensions\n    \"UP\",    # pyupgrade\n    \"ARG\",   # flake8-unused-arguments\n    \"SIM\",   # flake8-simplify\n]\nignore = [\n    \"E501\",    # Line too long (handled by formatter)\n    \"ARG002\",  # Unused method argument (common in interfaces/overrides)\n    \"B017\",    # assert-raises-exception\n    \"B023\",    # function-uses-loop-variable\n    \"B904\",    # raise-without-from-inside-except\n    \"SIM102\",  # collapsible-if\n    \"SIM105\",  # suppressible-exception\n    \"SIM108\",  # if-else-block-instead-of-if-exp\n    \"SIM117\",  # multiple-with-statements\n]\n\n[tool.ruff.lint.isort]\nforce-single-line = false\nforce-sort-within-sections = true\nknown-first-party = [\"ouroboros\"]\n\n[tool.ruff.lint.per-file-ignores]\n\"tests/**\" = [\"ARG001\", \"ARG002\", \"E402\"]\n# Executed by the task's own interpreter, down to Python 3.5: evaluated\n# annotations must use typing generics, and no f-strings are allowed\n# (boundary/harness.py docstring).\n\"src/ouroboros/boundary/harness.py\" = [\"UP006\", \"UP032\", \"UP035\", \"UP045\"]\n# Same constraint: the probe wrapper runs in the tree's interpreter\n# (examples/probe_wrapper.py docstring).\n\"src/ouroboros/examples/probe_wrapper.py\" = [\"UP006\", \"UP032\", \"UP035\", \"UP045\"]\n\n[tool.ruff.format]\nquote-style = \"double\"\nindent-style = \"space\"\n"
    }
